import * as THREE from 'three/webgpu';
import gsap from 'gsap';

const createNode = (config, ctx) => {
  const root = new THREE.Group();
  root.position.copy(config.position);
  root.rotation.setFromVector3(new THREE.Vector3(...config.rotation));
  root.scale.set(...config.scale);

  const colors = {
    ink: new THREE.Color(0x16161d),
    paper: new THREE.Color(0xe8ecf2),
    accent: new THREE.Color(0xff2a38),
  };

  const baseTexture = ctx.textureLoader.load('/prism-mock/home/nodes/parallax-stack.png');

  const cardWidth = 1.6;
  const cardHeight = 1.0;
  const cardPitch = 1.85;
  const numCards = 5;
  const stripRotationY = -18 * Math.PI / 180;
  const bevelSize = 0.025;
  const parallaxIntensity = 0.5;

  const filmstrip = new THREE.Group();
  filmstrip.rotation.y = stripRotationY;
  root.add(filmstrip);

  const captions = ['NA-01 MERIDIAN', 'NA-02 NOCTURNE', 'NA-03 SIGNAL', 'NA-04 VANTAGE', 'NA-05 ARCHIVE'];
  const cards = [];
  const bevelGeomsAndMats = [];

  for (let i = 0; i < numCards; i++) {
    const cardGroup = new THREE.Group();
    cardGroup.position.x = (i - 2) * cardPitch;

    const cardGeom = new THREE.PlaneGeometry(cardWidth, cardHeight);
    const cardMat = new THREE.MeshStandardMaterial({
      map: baseTexture,
      roughness: 0.55,
      metalness: 0.2,
      clearcoat: 0.15,
    });
    const cardMesh = new THREE.Mesh(cardGeom, cardMat);
    cardGroup.add(cardMesh);

    const bevelPoints = [
      new THREE.Vector3(-cardWidth / 2 - bevelSize, -cardHeight / 2 - bevelSize, 0.001),
      new THREE.Vector3(cardWidth / 2 + bevelSize, -cardHeight / 2 - bevelSize, 0.001),
      new THREE.Vector3(cardWidth / 2 + bevelSize, cardHeight / 2 + bevelSize, 0.001),
      new THREE.Vector3(-cardWidth / 2 - bevelSize, cardHeight / 2 + bevelSize, 0.001),
      new THREE.Vector3(-cardWidth / 2 - bevelSize, -cardHeight / 2 - bevelSize, 0.001),
    ];
    const bevelGeom = new THREE.BufferGeometry();
    bevelGeom.setFromPoints(bevelPoints);
    const bevelMat = new THREE.LineBasicMaterial({ color: colors.ink });
    const bevelLine = new THREE.Line(bevelGeom, bevelMat);
    cardGroup.add(bevelLine);

    bevelGeomsAndMats.push({ geom: bevelGeom, mat: bevelMat });

    cards.push({
      group: cardGroup,
      mesh: cardMesh,
      index: i,
      caption: captions[i],
      cardGeom: cardGeom,
      cardMat: cardMat,
      underline: null,
      captionMesh: null,
    });

    filmstrip.add(cardGroup);
  }

  const headlineTexture = ctx.fontAtlas.render('The collection', {
    family: 'Lora',
    fontSize: 68,
    fontWeight: 600,
    letterSpacing: -0.005,
    color: colors.paper,
  });
  const headlineMat = new THREE.MeshBasicMaterial({ map: headlineTexture, transparent: true });
  const headlineGeom = new THREE.PlaneGeometry(2.8, 0.4);
  const headlineMesh = new THREE.Mesh(headlineGeom, headlineMat);
  headlineMesh.position.set(-2.6, 1.5, 0);
  root.add(headlineMesh);

  const bodyTexture = ctx.fontAtlas.render('Five calibres. One discipline.', {
    family: 'JetBrains Mono',
    fontSize: 26,
    fontWeight: 400,
    color: colors.paper,
  });
  const bodyMat = new THREE.MeshBasicMaterial({ map: bodyTexture, transparent: true });
  const bodyGeom = new THREE.PlaneGeometry(3.5, 0.15);
  const bodyMesh = new THREE.Mesh(bodyGeom, bodyMat);
  bodyMesh.position.set(-2.6, -1.5, 0);
  root.add(bodyMesh);

  const state = {
    focusedIndex: 2,
    filmstripOffsetX: 0,
    scrollTimeout: null,
    snapTimeline: null,
  };

  const updateCardVisuals = () => {
    cards.forEach((card, idx) => {
      const distance = Math.abs(idx - state.focusedIndex);

      if (idx === state.focusedIndex) {
        card.group.rotation.y = 0;
        card.group.scale.set(1.0, 1.0, 1.0);
        card.mesh.material.opacity = 1.0;
        card.mesh.material.transparent = false;

        if (!card.underline) {
          const underlineGeom = new THREE.PlaneGeometry(cardWidth, 0.035);
          const underlineMat = new THREE.MeshStandardMaterial({
            emissive: colors.accent,
            emissiveIntensity: 1.3,
          });
          const underline = new THREE.Mesh(underlineGeom, underlineMat);
          underline.position.y = -cardHeight / 2 - 0.1;
          underline.position.z = 0.01;
          card.group.add(underline);
          card.underline = underline;
        }

        if (!card.captionMesh) {
          const captionTexture = ctx.fontAtlas.render(card.caption, {
            family: 'JetBrains Mono',
            fontSize: 18,
            fontWeight: 700,
            color: colors.paper,
          });
          const captionMat = new THREE.MeshBasicMaterial({ map: captionTexture, transparent: true });
          const captionGeom = new THREE.PlaneGeometry(1.2, 0.09);
          const captionMesh = new THREE.Mesh(captionGeom, captionMat);
          captionMesh.position.y = -cardHeight / 2 - 0.3;
          captionMesh.position.z = 0.01;
          card.group.add(captionMesh);
          card.captionMesh = captionMesh;
        }
      } else {
        card.group.rotation.y = 0;
        card.group.scale.set(0.92, 0.92, 0.92);
        const opacityDecay = (distance * 0.45) / (numCards - 1);
        const targetOpacity = Math.max(0.55, 1.0 - opacityDecay);
        card.mesh.material.opacity = targetOpacity;
        card.mesh.material.transparent = true;

        if (card.underline) {
          card.group.remove(card.underline);
          card.underline.geometry.dispose();
          card.underline.material.dispose();
          card.underline = null;
        }

        if (card.captionMesh) {
          card.group.remove(card.captionMesh);
          card.captionMesh.geometry.dispose();
          card.captionMesh.material.dispose();
          card.captionMesh = null;
        }
      }
    });
  };

  updateCardVisuals();

  const calculateFocusedIndex = (offsetX) => {
    const relativePos = -offsetX / cardPitch + 2;
    return Math.round(relativePos);
  };

  const snapToNearestCard = () => {
    if (state.snapTimeline) {
      state.snapTimeline.kill();
    }

    state.focusedIndex = calculateFocusedIndex(state.filmstripOffsetX);
    state.focusedIndex = Math.max(0, Math.min(numCards - 1, state.focusedIndex));

    const targetOffsetX = -(state.focusedIndex - 2) * cardPitch;

    state.snapTimeline = gsap.to(state, {
      filmstripOffsetX: targetOffsetX,
      duration: 0.9,
      ease: 'cubic-bezier(0.165, 0.84, 0.44, 1)',
      onUpdate: () => {
        filmstrip.position.x = state.filmstripOffsetX;
      },
      onComplete: () => {
        updateCardVisuals();
      },
    });

    updateCardVisuals();
  };

  root.userData.handlers = {
    scroll: (event) => {
      const deltaY = event.detail?.delta || 0;
      state.filmstripOffsetX += deltaY * parallaxIntensity;

      cards.forEach((card) => {
        if (card.mesh.material.map) {
          const uvShift = (state.filmstripOffsetX % 1) * 0.04;
          card.mesh.material.map.offset.x = uvShift;
        }
      });

      filmstrip.position.x = state.filmstripOffsetX;

      const potentialFocusedIndex = calculateFocusedIndex(state.filmstripOffsetX);
      if (potentialFocusedIndex !== state.focusedIndex) {
        state.focusedIndex = potentialFocusedIndex;
        updateCardVisuals();
      }

      if (state.scrollTimeout) clearTimeout(state.scrollTimeout);
      state.scrollTimeout = setTimeout(() => {
        snapToNearestCard();
      }, 200);
    },
  };

  if (ctx.primitives && ctx.primitives['parallax-scroll']) {
    ctx.primitives['parallax-scroll'](root, { intensity: parallaxIntensity });
  }

  root.userData.cleanup = () => {
    if (state.scrollTimeout) clearTimeout(state.scrollTimeout);
    if (state.snapTimeline) state.snapTimeline.kill();

    cards.forEach((card) => {
      card.cardGeom.dispose();
      card.cardMat.dispose();
      if (card.underline) {
        card.underline.geometry.dispose();
        card.underline.material.dispose();
      }
      if (card.captionMesh) {
        card.captionMesh.geometry.dispose();
        card.captionMesh.material.dispose();
      }
    });

    bevelGeomsAndMats.forEach(({ geom, mat }) => {
      geom.dispose();
      mat.dispose();
    });

    headlineGeom.dispose();
    headlineMat.dispose();
    headlineTexture.dispose();

    bodyGeom.dispose();
    bodyMat.dispose();
    bodyTexture.dispose();

    baseTexture.dispose();
  };

  return root;
};

export default createNode;
